-- NEW 1776 FORGE database only. NEVER run this against the legacy project.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS jurisdictions (id TEXT PRIMARY KEY, name TEXT NOT NULL, level TEXT NOT NULL CHECK(level IN ('federal','state','county','city','other')), parent_id TEXT REFERENCES jurisdictions(id), state_code TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS agencies (id TEXT PRIMARY KEY, jurisdiction_id TEXT NOT NULL REFERENCES jurisdictions(id), name TEXT NOT NULL, official_url TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE, google_subject TEXT UNIQUE, display_name TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'member' CHECK(role IN ('member','contributor','researcher','editor','admin','owner')), state TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS documents (id TEXT PRIMARY KEY, jurisdiction_id TEXT REFERENCES jurisdictions(id), agency_id TEXT REFERENCES agencies(id), title TEXT NOT NULL, document_type TEXT NOT NULL, record_date TEXT, published_date TEXT, source_url TEXT, original_storage_key TEXT, original_sha256 TEXT, mime_type TEXT, verification_state TEXT NOT NULL DEFAULT 'unreviewed', visibility TEXT NOT NULL DEFAULT 'public', imported_legacy_id TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS documents_legacy_id ON documents(imported_legacy_id) WHERE imported_legacy_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS documents_by_jurisdiction_date ON documents(jurisdiction_id,record_date);
CREATE TABLE IF NOT EXISTS resource_links (id TEXT PRIMARY KEY, name TEXT NOT NULL, url TEXT NOT NULL, description TEXT NOT NULL, jurisdiction_id TEXT REFERENCES jurisdictions(id), source_kind TEXT NOT NULL DEFAULT 'official', category TEXT NOT NULL, last_checked_at TEXT, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS legal_authorities (id TEXT PRIMARY KEY, title TEXT NOT NULL, authority_type TEXT NOT NULL, jurisdiction_id TEXT REFERENCES jurisdictions(id), citation TEXT, enacted_at TEXT, effective_at TEXT, repealed_at TEXT, source_url TEXT NOT NULL, version_label TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS articles (id TEXT PRIMARY KEY, slug TEXT UNIQUE NOT NULL, title TEXT NOT NULL, summary TEXT, body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','review','published','archived')), access_level TEXT NOT NULL DEFAULT 'public' CHECK(access_level IN ('public','member','premium')), author_id TEXT REFERENCES users(id), published_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS content_links (id TEXT PRIMARY KEY, source_type TEXT NOT NULL, source_id TEXT NOT NULL, target_type TEXT NOT NULL, target_id TEXT NOT NULL, relationship TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(source_type,source_id,target_type,target_id,relationship));
CREATE TABLE IF NOT EXISTS discussions (id TEXT PRIMARY KEY, jurisdiction_id TEXT REFERENCES jurisdictions(id), context_type TEXT NOT NULL, context_id TEXT, title TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id), moderation_state TEXT NOT NULL DEFAULT 'visible', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS comments (id TEXT PRIMARY KEY, discussion_id TEXT NOT NULL REFERENCES discussions(id), parent_id TEXT REFERENCES comments(id), author_id TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, moderation_state TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT);
CREATE INDEX IF NOT EXISTS comments_by_discussion ON comments(discussion_id,created_at);
CREATE TABLE IF NOT EXISTS map_features (id TEXT PRIMARY KEY, jurisdiction_id TEXT REFERENCES jurisdictions(id), kind TEXT NOT NULL, title TEXT NOT NULL, geometry_geojson TEXT NOT NULL, condition_state TEXT, status TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS map_reports (id TEXT PRIMARY KEY, feature_id TEXT REFERENCES map_features(id), author_id TEXT REFERENCES users(id), title TEXT NOT NULL, description TEXT NOT NULL, review_state TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS moderation_events (id TEXT PRIMARY KEY, actor_id TEXT REFERENCES users(id), target_type TEXT NOT NULL, target_id TEXT NOT NULL, action TEXT NOT NULL, reason TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, actor_id TEXT, action TEXT NOT NULL, subject_type TEXT NOT NULL, subject_id TEXT, details_json TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
